"""Release UI for Scribbler 4.x.

This is presentation only. It deliberately calls the existing tagging and analysis
APIs rather than creating a second set of engines.
"""
APP = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audhd Scribbler</title><style>
:root{--ink:#26312f;--muted:#6e7773;--paper:#f7f6f1;--panel:#fff;--line:#ddd9d0;--accent:#52777a;--soft:#e7efed;--warm:#f3eee4;--danger:#fff0ed}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.55 Segoe UI,Arial,sans-serif}.top{height:72px;background:#26312f;color:#fff;display:flex;align-items:center;padding:0 30px;gap:18px;position:sticky;top:0;z-index:20}.brand{font:700 25px Georgia}.tagline{opacity:.65}.status{margin-left:auto;font-size:12px;opacity:.8}.app{display:grid;grid-template-columns:220px minmax(0,1120px);max-width:1450px;margin:auto;min-height:calc(100vh - 72px)}aside{background:#efede7;border-right:1px solid var(--line);padding:22px 12px}aside h5{margin:16px 10px 7px;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:1.3px}nav button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:11px 12px;border-radius:8px;color:var(--ink);cursor:pointer}nav button:hover,nav button.active{background:#dce8e5}main{padding:34px 40px 60px}.view{display:none}.view.active{display:block}h1{font:700 35px Georgia;margin:0 0 6px}h2{font:700 24px Georgia;margin:0 0 7px}h3{font:700 17px Georgia;margin:0 0 5px}.lead{color:var(--muted);max-width:820px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:24px 0}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px}.card p,.muted{color:var(--muted)}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}.btn{border:1px solid var(--line);background:#fff;color:var(--ink);padding:9px 13px;border-radius:7px;cursor:pointer}.btn:hover{border-color:#aeb9b5}.primary{background:var(--accent);border-color:var(--accent);color:#fff}.filelist{border:1px solid var(--line);border-radius:9px;background:#fff;max-height:440px;overflow:auto}.file{display:flex;gap:12px;align-items:center;padding:12px;border-bottom:1px solid var(--line)}.file:last-child{border:0}.file input{width:18px;height:18px}.meta{margin-left:auto;color:var(--muted);font-size:12px}.tools{display:grid;grid-template-columns:repeat(2,1fr);gap:11px}.tool{display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:10px;padding:14px;background:#fff}.tool.selected{background:var(--soft);border-color:var(--accent)}.tool input{margin-top:4px}.toolbody{flex:1}.tooltitle{font-weight:700}.toolmeta{font-size:11px;color:var(--muted);margin-top:3px}.toolrun{font-size:11px;padding:5px 8px;border:1px solid var(--line);background:#fff;border-radius:6px;cursor:pointer}.results{display:grid;gap:14px}.result{border:1px solid var(--line);border-radius:10px;background:#fff;padding:17px}.resulthead{display:flex;justify-content:space-between;gap:15px;align-items:start}.badge{font-size:10px;padding:4px 8px;border-radius:10px;background:var(--soft)}.finding{margin-top:12px;padding:11px;background:#f3f1eb;border-radius:8px}.finding b{display:block;margin-bottom:3px}.kv{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.kv div{background:#f7f6f1;border-radius:7px;padding:9px}.kv span{display:block;color:var(--muted);font-size:11px}.kv strong{font-size:16px}.json{margin-top:10px;background:#222b29;color:#edf2ef;border-radius:8px;padding:12px;white-space:pre-wrap;font:12px Consolas;max-height:300px;overflow:auto}.notearea{min-height:230px;width:100%;resize:vertical}.input{width:100%;padding:10px;border:1px solid var(--line);border-radius:7px;font:inherit}.notice{padding:12px;border-radius:8px;background:var(--soft);margin:12px 0}.warning{background:#f7efe2}.empty{text-align:center;padding:34px;color:var(--muted)}.saveok{background:#edf4ef;padding:12px;border-radius:8px}.modal{position:fixed;inset:0;background:#17201d88;z-index:50;display:none;align-items:center;justify-content:center;padding:25px}.modal.open{display:flex}.dialog{background:#fff;width:min(900px,95vw);max-height:90vh;overflow:auto;border-radius:14px;padding:25px}.taggrid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.tagitem{background:var(--soft);padding:10px;border-radius:8px}.version{font-size:10px;color:var(--muted);margin:20px 10px}@media(max-width:850px){.app{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line);padding:8px;overflow:auto}nav{display:flex;gap:4px}nav button{white-space:nowrap;width:auto}main{padding:22px}.grid,.tools,.taggrid,.kv{grid-template-columns:1fr}.tagline{display:none}}
</style></head><body><header class="top"><div class="brand">Audhd Scribbler</div><div class="tagline">organise the mess · develop the writing · understand the patterns</div><div id="status" class="status">Ready</div></header><div class="app"><aside><nav><h5>Organise</h5><button data-v="home" class="active">Home</button><button data-v="inbox">Scribble Inbox</button><h5>Develop</h5><button data-v="manuscript">Manuscript</button><h5>Understand</h5><button data-v="analysis">Analysis Suite</button><h5>Protect</h5><button data-v="notes">Quick Note</button><button data-v="safety">Export & Safety</button></nav><div class="version">Scribbler 4.x · Windows</div></aside><main>
<section id="home" class="view active"><h1>Your writing workshop</h1><p class="lead">Two deliberately separate worlds: <b>Inbox</b> for messy material and tagging; <b>Manuscript</b> for actual drafts and analysis. Scribbler never decides that a brain dump is a draft.</p><div class="grid"><div class="card"><h3>01 · Scribble Inbox</h3><p>Dump ideas, transcripts and fragments here. Preview and apply tags without analysing the prose.</p><button class="btn primary" onclick="go('inbox')">Open Inbox</button></div><div class="card"><h3>02 · Manuscript</h3><p>Import chapters and drafts. This is the only material analysis is allowed to touch.</p><button class="btn primary" onclick="go('manuscript')">Open Manuscript</button></div><div class="card"><h3>03 · Analysis</h3><p>Choose the exact chapter and the exact question. Each tool is real and reports its findings.</p><button class="btn primary" onclick="go('analysis')">Open Analysis</button></div></div><div class="panel"><h3>The rule that keeps Scribbler sane</h3><p><b>Tagging organises raw material. Analysis examines writing.</b> They are separate operations, separate screens and separate API endpoints.</p></div></section>
<section id="inbox" class="view"><h1>Scribble Inbox</h1><p class="lead">Brain dumps, voice-to-text, fragments, notes and half-formed ideas. Nothing here is treated as a manuscript.</p><div class="actions"><button class="btn primary" onclick="upload('raw-dumps')">＋ Import raw dump(s)</button><button class="btn" onclick="go('notes')">＋ Write a quick note</button><button class="btn" onclick="previewTags()">Preview tags</button><button class="btn primary" onclick="applyTags()">Apply tags</button></div><div class="notice">Tagging can identify <b>people, places, themes, era, voice, emotional register and sensory signals</b>. AI assistance is optional. Your prose is not rewritten.</div><div class="panel"><div id="inboxList" class="filelist"></div></div><div class="panel"><h3>Tagging results</h3><div id="tagResults" class="results"><div class="empty">Select Inbox material and preview or apply tags.</div></div></div></section>
<section id="manuscript" class="view"><h1>Manuscript</h1><p class="lead">Chapters, drafts and final material. Importing here is what makes material eligible for analysis.</p><div class="actions"><button class="btn primary" onclick="upload('chapters')">＋ Import chapter(s)</button><button class="btn" onclick="upload('drafts')">＋ Import draft(s)</button><button class="btn" onclick="go('analysis')">Open Analysis Suite</button></div><div class="notice">Inbox material is intentionally excluded from analysis. If a dump becomes a chapter, import a copy here; the original remains in the Inbox.</div><div class="panel"><div id="manuscriptList" class="filelist"></div></div></section>
<section id="analysis" class="view"><h1>Analysis Suite</h1><p class="lead">Seventeen explicit tools. No tagging occurs here. Select manuscript material, then run one tool or a compatible set.</p><div class="panel"><h3>1 · Choose manuscript material</h3><div id="analysisList" class="filelist"></div></div><div class="panel"><h3>2 · Choose an analysis</h3><div id="tools" class="tools"></div><div class="actions"><button class="btn" onclick="recommended()">Recommended</button><button class="btn" onclick="allTools()">Select all</button><button class="btn" onclick="clearTools()">Clear</button><button class="btn primary" onclick="runSelected()">Run selected</button></div><div class="notice warning"><b>Run All is deliberately cautious.</b> Different tools answer different questions. Scribbler will run what you select, but will not turn a finding into a correction.</div></div><div class="panel"><h3>Results</h3><div id="analysisResults" class="results"><div class="empty">Choose manuscript material and an analysis tool.</div></div></div></section>
<section id="notes" class="view"><h1>Quick Note</h1><p class="lead">A thought shouldn't have to wait until you know where it belongs.</p><div class="panel"><input id="noteTitle" class="input" placeholder="Optional title"><br><br><textarea id="noteText" class="input notearea" placeholder="Write the thought, memory, line, question or fragment here…"></textarea><div class="actions"><button class="btn primary" onclick="saveNote()">Save to Scribble Inbox</button></div></div></section>
<section id="safety" class="view"><h1>Export & Safety</h1><p class="lead">Scribbler is designed to make experimentation safe: snapshots before changes, analysis history retained, exports never silently overwrite.</p><div class="panel"><h3>Portable project backup</h3><p class="muted">Creates a ZIP containing your writing folders, database and project manifest.</p><button class="btn primary" onclick="backup()">Create backup ZIP</button></div><div class="panel"><h3>Export manuscript</h3><div id="exportList" class="filelist"></div><div class="actions"><button class="btn" onclick="exportFile('docx')">DOCX</button><button class="btn" onclick="exportFile('md')">Markdown</button><button class="btn" onclick="exportFile('txt')">Plain text</button></div></div></section>
</main></div><input id="upload" type="file" multiple accept=".txt,.md,.text" hidden><div id="modal" class="modal"><div id="dialog" class="dialog"></div></div><script>
let DATA={files:[],tools:{},catalog:{}};const status=document.getElementById('status');const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const setStatus=x=>status.textContent=x;
function go(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.v===id));render()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.v));
async function load(){DATA=await(await fetch('/api/files',{cache:'no-store'})).json();let t=await(await fetch('/api/tools',{cache:'no-store'})).json();DATA.tools=t.tools||{};DATA.catalog=t.catalog||{}}
function by(folders){return (DATA.files||[]).filter(x=>folders.includes(x.folder))}
function list(items,scope){if(!items.length)return '<div class="empty">Nothing here yet.</div>';return items.map(x=>`<label class="file"><input type="checkbox" data-s="${scope}" value="${esc(x.path)}"><span><b>${esc(x.filename)}</b><br><span class="muted">${x.word_count||0} words · ${esc(x.status)}${x.last_analyzed?' · analysed':''}</span></span><span class="meta">${esc(x.folder)}</span></label>`).join('')}
function selected(scope){return [...document.querySelectorAll(`input[data-s="${scope}"]:checked`)].map(x=>x.value)}
function render(){document.getElementById('inboxList').innerHTML=list(by(['raw-dumps','triage']),'inbox');document.getElementById('manuscriptList').innerHTML=list(by(['chapters','drafts','final']),'manuscript');document.getElementById('analysisList').innerHTML=list(by(['chapters','drafts','final']),'analysis');document.getElementById('exportList').innerHTML=list(by(['chapters','drafts','final']),'export');renderTools()}
function renderTools(){const order=['craft','voice','characters','continuity','themes','editor','repetition','pacing','structure','memoir','reader','research','cadence','motifs','anchors','voice_dna','reader_perception'];document.getElementById('tools').innerHTML=order.filter(k=>DATA.tools[k]).map(k=>{let t=DATA.tools[k],c=DATA.catalog[k]||{};return `<div class="tool" id="tool-${k}"><input type="checkbox" class="toolbox" value="${k}" onchange="this.closest('.tool').classList.toggle('selected',this.checked)"><div class="toolbody"><div class="tooltitle">${esc(t.title)}</div><div class="toolmeta">${esc(t.group)} · ${esc(c.stage||'draft')} · ${esc(t.purpose)}</div></div><button class="toolrun" onclick="runOne('${k}')">Run</button></div>`}).join('')}
async function upload(destination){let i=document.getElementById('upload');i.value='';i.onchange=async()=>{if(!i.files.length)return;let fd=new FormData();fd.append('destination',destination);[...i.files].forEach(f=>fd.append('files',f));setStatus('Saving copies…');let j=await(await fetch('/api/import',{method:'POST',body:fd})).json();if(!j.ok)return alert(j.error);await load();render();setStatus('✓ '+j.message);go(destination==='raw-dumps'?'inbox':'manuscript')};i.click()}
async function previewTags(){let p=selected('inbox');if(!p.length)return alert('Select one or more brain dumps first.');setStatus('Reading for tag candidates…');let j=await(await fetch('/api/tag-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:p,use_ai:false})})).json();if(!j.ok)return alert(j.error);document.getElementById('tagResults').innerHTML=j.preview.map(x=>`<div class="result"><h3>${esc(x.filename)}</h3><div class="kv"><div><span>Voice</span><strong>${esc(x.voice||'—')}</strong></div><div><span>Era</span><strong>${esc(x.era||'—')}</strong></div><div><span>Emotion</span><strong>${esc(x.emotional_register||'—')}</strong></div></div><div class="taggrid" style="margin-top:10px">${[['Themes',x.themes],['Characters',x.characters],['Places',x.places],['Sensory',x.sensory]].map(a=>`<div class="tagitem"><b>${a[0]}</b><br>${esc(Array.isArray(a[1])?a[1].join(', '):(a[1]||'—'))}</div>`).join('')}</div></div>`).join('');setStatus('✓ Tag preview ready')}
async function applyTags(){let p=selected('inbox');if(!p.length)return alert('Select one or more brain dumps first.');if(!confirm(`Apply tags to ${p.length} brain dump(s)? A safety snapshot is created first. The prose body is not rewritten.`))return;setStatus('Tagging…');let j=await(await fetch('/api/tag',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:p,use_llm:true})})).json();if(!j.ok)return alert(j.error);await load();render();setStatus(`✓ Tagged ${j.tagged.length} item(s)`);document.getElementById('tagResults').innerHTML=`<div class="saveok"><b>Tagging saved.</b><br>${j.tagged.length} item(s) processed. ${j.errors?.length||0} error(s). Your prose was not rewritten.</div>`}
function clearTools(){document.querySelectorAll('.toolbox').forEach(x=>{x.checked=false;x.closest('.tool').classList.remove('selected')})}function allTools(){document.querySelectorAll('.toolbox').forEach(x=>{x.checked=true;x.closest('.tool').classList.add('selected')})}function recommended(){clearTools();['craft','voice','characters','continuity','themes','cadence','motifs','anchors'].forEach(k=>{let x=document.querySelector(`.toolbox[value="${k}"]`);if(x){x.checked=true;x.closest('.tool').classList.add('selected')}})}
async function runOne(k){clearTools();let x=document.querySelector(`.toolbox[value="${k}"]`);if(x){x.checked=true;x.closest('.tool').classList.add('selected')}await runSelected()}
function pretty(tool,data){let flat=[];function walk(v,path=''){if(v==null)return;if(Array.isArray(v)){if(v.length&&typeof v[0]==='object')flat.push({label:path,value:v});return}if(typeof v==='object'){for(const [k,x] of Object.entries(v)){if(k==='analysis')continue;if(['note','message','status'].includes(k)&&typeof x==='string'){flat.push({label:path?path+' · '+k:k,value:x});continue}walk(x,path?path+' · '+k:k)}}else flat.push({label:path,value:v})}walk(data);return flat.slice(0,12)}
function resultCard(file,tool,data){let title=(DATA.tools[tool]||{}).title||tool, items=pretty(tool,data);return `<div class="result"><div class="resulthead"><div><h3>${esc(file)}</h3><div class="muted">${esc(title)}</div></div><span class="badge">saved</span></div><div class="kv">${items.filter(x=>typeof x.value!=='object').slice(0,6).map(x=>`<div><span>${esc(x.label)}</span><strong>${esc(String(x.value))}</strong></div>`).join('')}</div>${items.filter(x=>typeof x.value==='object').map(x=>`<div class="finding"><b>${esc(x.label)}</b>${esc(JSON.stringify(x.value,null,2))}</div>`).join('')}<details><summary>Full evidence</summary><div class="json">${esc(JSON.stringify(data,null,2))}</div></details></div>`}
async function runSelected(){let p=selected('analysis'),t=[...document.querySelectorAll('.toolbox:checked')].map(x=>x.value);if(!p.length)return alert('Select one or more chapters/drafts first.');if(!t.length)return alert('Choose at least one analysis tool.');if(!confirm(`Run ${t.length} analysis tool(s) across ${p.length} manuscript item(s)? A safety snapshot is created first.`))return;setStatus('Analysing…');let j=await(await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:p,tools:t})})).json();if(!j.ok)return alert(j.error);document.getElementById('analysisResults').innerHTML=j.results.flatMap(r=>Object.entries(r.results).map(([k,v])=>resultCard(r.filename,k,v))).join('')||'<div class="empty">No results returned.</div>';setStatus('✓ '+j.message)}
async function saveNote(){let text=document.getElementById('noteText').value.trim();if(!text)return alert('Write something first.');let j=await(await fetch('/api/note',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:document.getElementById('noteTitle').value,text})})).json();if(!j.ok)return alert(j.error);document.getElementById('noteText').value='';document.getElementById('noteTitle').value='';await load();render();setStatus('✓ Saved to Scribble Inbox');go('inbox')}
async function backup(){setStatus('Creating backup…');let j=await(await fetch('/api/backup',{method:'POST'})).json();if(!j.ok)return alert(j.error);setStatus('✓ Backup created');alert('Portable backup created at:\n'+j.path)}
async function exportFile(kind){let p=selected('export')[0];if(!p)return alert('Select one manuscript file first.');let j=await(await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:p,kind})})).json();if(!j.ok)return alert(j.error);setStatus('✓ Export created');alert('Export created at:\n'+j.path)}
load().then(render).catch(e=>{setStatus('Load error');alert('Scribbler could not load its workspace: '+e)})
</script></body></html>'''
